/* 0032_general_price_from_niches.sql, flattened for the Supabase SQL editor. Generated by scripts/flatten-migration.mjs - do not edit this file, edit the migration and run the script again. One statement per line, no line comments, nothing to lose to a newline. The commentary lives in the migration itself. */
insert into public.service_costs (service_id, cost_price_minor, updated_by) select service.id, cheapest.rate, 'migration 0032' from public.services as service join lateral ( select min(niche.cost_minor) as rate from public.website_niche_costs as niche where niche.website_id = service.website_id and niche.link_type = service.type and niche.assumed = false ) as cheapest on cheapest.rate is not null where not exists ( select 1 from public.service_costs as existing where existing.service_id = service.id and coalesce(existing.cost_price_minor, 0) > 0 ) on conflict (service_id) do update set cost_price_minor = excluded.cost_price_minor where coalesce(public.service_costs.cost_price_minor, 0) = 0;
update public.services set available = false where available = true and price_minor <= 0;
update public.websites as site set status = 'draft' where site.status = 'active' and not exists ( select 1 from public.services as service where service.website_id = site.id and service.available = true and service.price_minor > 0 );
